<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Illuminate\Support\Facades\Cache; class PlayerFiles { private const TTL = 30; public static function dirs(ServerFiles $files, string $server): array { return Cache::remember( "dezerx:playerlayout:{$server}", self::TTL, fn () => self::resolve($files, PlayerRoster::levelName($files, $server)), ); } public static function resolve(ServerFiles $files, string $level): array { if (is_array($files->listFiles("/{$level}/players/data"))) { return [ 'level' => $level, 'data' => "/{$level}/players/data", 'stats' => "/{$level}/players/stats", 'advancements' => "/{$level}/players/advancements", ]; } return [ 'level' => $level, 'data' => "/{$level}/playerdata", 'stats' => "/{$level}/stats", 'advancements' => "/{$level}/advancements", ]; } } 